"""Brute-force reference for the canonical image, used to test the compiler."""
import itertools, sys
sys.path[:0] = ['/opt/emicro-deps', '/workspace/project']
from syntax import parse, MATCH, STARTSWITH, ENDSWITH, CONTAINS, AND, OR, NOT, ALLOW, DROP
from ebpf.create_dfa import create, registry_columns

DENY = 4294967295


def ev(node, w):
    k = node[0]
    if k == MATCH:
        return w == node[1]
    if k == STARTSWITH:
        p = node[1]
        return len(w) >= len(p) and w[:len(p)] == p
    if k == ENDSWITH:
        p = node[1]
        return len(w) >= len(p) and (len(p) == 0 or w[-len(p):] == p)
    if k == CONTAINS:
        p = node[1]
        if not p:
            return True
        n = len(w); m = len(p)
        for i in range(n - m + 1):
            if w[i:i+m] == p:
                return True
        return False
    if k == AND:
        return ev(node[1], w) and ev(node[2], w)
    if k == OR:
        return ev(node[1], w) or ev(node[2], w)
    return not ev(node[1], w)


def compile_rules_ref(rules):
    allow = [n for n, a in rules if a == ALLOW]
    drop = [n for n, a in rules if a == DROP]
    def allowed(w):
        if not any(ev(n, w) for n in allow):
            return False
        if any(ev(n, w) for n in drop):
            return False
        return True
    return allowed


def brute_image(text, cols, colmap, depth_words, depth_conts):
    """Canonical image by explicit Myhill-Nerode classes over bounded words."""
    res = parse(text)
    names = res.names
    cols_of = [colmap[names[i]] for i in range(len(names))]
    rules = [(_rename(n, cols_of), a) for n, a in res.rules]
    allowed = compile_rules_ref(rules)
    m = len(cols)
    memo = {}
    def acc(w):
        v = memo.get(w)
        if v is None:
            v = allowed(w)
            memo[w] = v
        return v
    words = []
    frontier = [()]
    words.append(())
    for _ in range(depth_words + depth_conts):
        nxt = []
        for w in frontier:
            for c in range(m):
                x = w + (c,)
                nxt.append(x)
        words.extend(nxt)
        frontier = nxt
    conts = []
    frontier = [()]
    conts.append(())
    for _ in range(depth_conts):
        nxt = []
        for w in frontier:
            for c in range(m):
                nxt.append(w + (c,))
        conts.extend(nxt)
        frontier = nxt
    sig_of = {}
    def sig(w):
        s = sig_of.get(w)
        if s is None:
            s = bytes(1 if acc(w + v) else 0 for v in conts)
            sig_of[w] = s
        return s
    cls = {}     # sig -> class id
    def class_of(w):
        s = sig(w)
        c = cls.get(s)
        if c is None:
            c = len(cls)
            cls[s] = c
        return c
    dead_sig = bytes(len(conts))
    # BFS from START over classes
    order = [()]
    index = {class_of(()): 0}
    rep = {0: ()}
    queue = [0]
    head = 0
    trans = {}
    while head < len(queue):
        cid = queue[head]; head += 1
        w = rep[cid]
        row = []
        for c in range(m):
            t = w + (c,)
            if sig(t) == dead_sig:
                row.append(DENY)
                continue
            tc = class_of(t)
            if tc not in index:
                index[tc] = len(index)
                rep[tc] = t
                queue.append(tc)
            row.append(index[tc])
        trans[cid] = row
    rows = [trans[index[class_of(rep[c])]] for c in range(len(index))]
    # accept[c] = allowedness of a history in that class (empty continuation)
    accept = [acc(rep[c]) for c in range(len(index))]
    return {'accept': accept, 'rows': rows}


def _rename(node, cols_of):
    k = node[0]
    if k <= CONTAINS:
        return (k, tuple(cols_of[i] for i in node[1]), None)
    if k == NOT:
        return (k, _rename(node[1], cols_of), None)
    return (k, _rename(node[1], cols_of), _rename(node[2], cols_of))


def compare(text, registry, dw=5, dc=5, verbose=True):
    cols, colmap = registry_columns(registry)
    got = create(text, cols, colmap)
    got_img = {'accept': list(got.accept), 'rows': [list(r) for r in got.rows]}
    ref = brute_image(text, cols, colmap, dw, dc)
    ok = got_img == ref
    if not ok and verbose:
        print('MISMATCH', repr(text))
        print(' got', got_img['accept'])
        for r in got_img['rows']:
            print('   ', r)
        print(' ref', ref['accept'])
        for r in ref['rows']:
            print('   ', r)
    return ok
PYEOF
